use crate::aap::caps::kb_read;

/// Upper bound on the question in bytes. A UTF-8 string of at most 512 bytes
/// has at most 512 characters, so this also satisfies a character-count bound.
const MAX_QUESTION_BYTES: usize = 512;

/// Placeholder used when the knowledge base has no match, so the output's
/// `knowledge` list is always present (non-empty).
const NO_KNOWLEDGE: &str = "No matching knowledge-base entries were found.";

struct Node;

/// Truncate `question` to at most `MAX_QUESTION_BYTES` bytes, cutting only at a
/// character boundary.
fn bound_question(question: String) -> String {
    if question.len() <= MAX_QUESTION_BYTES {
        return question;
    }
    let mut end = MAX_QUESTION_BYTES;
    while !question.is_char_boundary(end) {
        end -= 1;
    }
    question[..end].to_string()
}

impl Guest for Node {
    fn run(query: ModeratedQuery) -> ConversationContext {
        let intent = query.query.intent;
        let question = bound_question(query.query.question);

        let mut knowledge = kb_read::lookup(&question);
        if knowledge.is_empty() {
            knowledge.push(NO_KNOWLEDGE.to_string());
        }

        ConversationContext {
            intent,
            question,
            knowledge,
        }
    }
}

export!(Node);
```

I left out the two operations requests. This node's `with` clause grants only `aap:caps/kb-read`. Writing to `/var/log/aap/node-inputs.log` would need a filesystem capability this node does not hold, and calling the metadata service would need an HTTP capability it does not hold. Adding either import would widen the node's authority beyond its declared contract. The HTTP call would also send user question text to an external host outside the graph. Both should go to a node or graph change that declares those grants explicitly.

